package com.brandempiricism.etocrm.platform.tenancy;
import jakarta.persistence.*;import java.time.Instant;import java.util.UUID;
@Entity @Table(name="tenant_registry")class TenantRegistryEntity{@Id UUID id;String slug;String displayName;String website;String databaseName;String credentialSecretRef;@Enumerated(EnumType.STRING)TenantStatus status;@Enumerated(EnumType.STRING)ProvisioningStep provisioningStep;String failureCode;String idempotencyKey;Instant createdAt;String createdBy;Instant updatedAt;String updatedBy;protected TenantRegistryEntity(){}TenantRegistryEntity(UUID id,String slug,String displayName,String website,String databaseName,String idempotencyKey,Instant now,String actor){this.id=id;this.slug=slug;this.displayName=displayName;this.website=website;this.databaseName=databaseName;this.idempotencyKey=idempotencyKey;this.status=TenantStatus.PROVISIONING;this.provisioningStep=ProvisioningStep.REGISTERED;this.createdAt=now;this.createdBy=actor;this.updatedAt=now;this.updatedBy=actor;}}
enum TenantStatus{PROVISIONING,ACTIVE,SUSPENDED,CLOSED,FAILED}
enum ProvisioningStep{REGISTERED,DATABASE_ALLOCATED,MIGRATED,DEFAULTS_SEEDED,VERIFIED,ADMIN_ASSIGNED,COMPLETE}
